"""Go TDD strategy: per-package tests, generated files, doc.go and cmd mains (Plan 00527)."""

from pathlib import Path

import pytest

from claude_code_hooks_daemon.strategies.tdd.go_strategy import GoTddStrategy


def _module(root: Path) -> Path:
    """Make ``root`` a Go module and return it."""
    root.mkdir(parents=True, exist_ok=True)
    (root / "go.mod").write_text("module example.com/app\n")
    return root


class TestPerPackageTests:
    """Go tests per package: any *_test.go in the directory covers a new file."""

    def test_new_file_in_package_with_tests_is_skipped(self, tmp_path: Path) -> None:
        pkg = _module(tmp_path / "app") / "server"
        pkg.mkdir()
        (pkg / "server_test.go").write_text("package server\n")
        assert GoTddStrategy().should_skip(str(pkg / "routes.go"), "package server\n") is True

    def test_external_test_package_counts(self, tmp_path: Path) -> None:
        pkg = _module(tmp_path / "app") / "server"
        pkg.mkdir()
        (pkg / "api_test.go").write_text("package server_test\n")
        assert GoTddStrategy().should_skip(str(pkg / "routes.go"), "") is True

    def test_new_file_in_package_without_tests_is_gated(self, tmp_path: Path) -> None:
        pkg = _module(tmp_path / "app") / "server"
        pkg.mkdir()
        (pkg / "other.go").write_text("package server\n")
        assert GoTddStrategy().should_skip(str(pkg / "routes.go"), "package server\n") is False

    def test_tests_in_sibling_directory_do_not_count(self, tmp_path: Path) -> None:
        mod = _module(tmp_path / "app")
        (mod / "a").mkdir()
        (mod / "b").mkdir()
        (mod / "a" / "a_test.go").write_text("package a\n")
        assert GoTddStrategy().should_skip(str(mod / "b" / "b.go"), "") is False

    def test_missing_directory_is_gated(self, tmp_path: Path) -> None:
        mod = _module(tmp_path / "app")
        assert GoTddStrategy().should_skip(str(mod / "new" / "b.go"), "") is False


class TestGeneratedFiles:
    @pytest.mark.parametrize(
        "name", ["service.pb.go", "thing_gen.go", "zz_generated.deepcopy.go", "zz_generated_x.go"]
    )
    def test_generated_names_are_excluded(self, tmp_path: Path, name: str) -> None:
        mod = _module(tmp_path / "app")
        assert GoTddStrategy().is_excluded_source_file(str(mod / name)) is True

    def test_header_marks_file_generated(self, tmp_path: Path) -> None:
        content = "// Code generated by mockgen. DO NOT EDIT.\n\npackage mocks\n"
        mod = _module(tmp_path / "app")
        assert GoTddStrategy().should_skip(str(mod / "mock_store.go"), content) is True

    def test_header_after_licence_comment(self, tmp_path: Path) -> None:
        content = "// Copyright X\n\n// Code generated by stringer; DO NOT EDIT.\n\npackage p\n"
        mod = _module(tmp_path / "app")
        assert GoTddStrategy().should_skip(str(mod / "op_string.go"), content) is True

    def test_header_after_package_clause_does_not_count(self, tmp_path: Path) -> None:
        content = "package p\n\n// Code generated by x. DO NOT EDIT.\n"
        mod = _module(tmp_path / "app")
        assert GoTddStrategy().should_skip(str(mod / "real.go"), content) is False

    def test_header_without_do_not_edit_does_not_count(self, tmp_path: Path) -> None:
        content = "// Code generated by hand\n\npackage p\n"
        mod = _module(tmp_path / "app")
        assert GoTddStrategy().should_skip(str(mod / "real.go"), content) is False

    def test_ordinary_name_is_not_excluded(self, tmp_path: Path) -> None:
        mod = _module(tmp_path / "app")
        assert GoTddStrategy().is_excluded_source_file(str(mod / "server.go")) is False


class TestDocAndCmdMain:
    def test_doc_go_is_excluded(self, tmp_path: Path) -> None:
        mod = _module(tmp_path / "app")
        assert GoTddStrategy().is_excluded_source_file(str(mod / "api" / "doc.go")) is True

    def test_cmd_main_go_is_excluded(self, tmp_path: Path) -> None:
        mod = _module(tmp_path / "app")
        assert GoTddStrategy().is_excluded_source_file(str(mod / "cmd" / "t" / "main.go")) is True

    def test_cmd_other_file_is_not_excluded(self, tmp_path: Path) -> None:
        mod = _module(tmp_path / "app")
        assert GoTddStrategy().is_excluded_source_file(str(mod / "cmd" / "t" / "run.go")) is False

    def test_root_main_go_is_not_excluded(self, tmp_path: Path) -> None:
        mod = _module(tmp_path / "app")
        assert GoTddStrategy().is_excluded_source_file(str(mod / "main.go")) is False

    def test_main_go_outside_cmd_is_not_excluded(self, tmp_path: Path) -> None:
        mod = _module(tmp_path / "app")
        assert GoTddStrategy().is_excluded_source_file(str(mod / "x" / "y" / "main.go")) is False
